/**
 * Initial Prisma migration — sets up the schema, then enables the
 * pg_uuidv7 and TimescaleDB extensions. This is hand-rolled so we can
 * control the order of operations (extensions must exist before the
 * tables that depend on them).
 *
 * Run with:
 *   pnpm --filter @carenest/database prisma migrate dev --create-only --name init
 * Then paste the body of this file into the generated migration, replacing
 * the body of the auto-generated `migration.sql`.
 */

-- 1) Extensions (must come before any uuidv7() usage in defaults)
CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE EXTENSION IF NOT EXISTS "pg_uuidv7";
CREATE EXTENSION IF NOT EXISTS "timescaledb";

-- 2) Enums
CREATE TYPE "UserRole"           AS ENUM ('BUYER','SELLER','ADMIN','SUPPORT','CAREGIVER');
CREATE TYPE "UserStatus"         AS ENUM ('ACTIVE','SUSPENDED','PENDING_VERIFICATION','DEACTIVATED');
CREATE TYPE "SellerStatus"       AS ENUM ('DRAFT','PENDING_REVIEW','ACTIVE','SUSPENDED','REJECTED');
CREATE TYPE "KycStatus"          AS ENUM ('NOT_STARTED','IN_REVIEW','APPROVED','REJECTED','EXPIRED');
CREATE TYPE "OrderStatus"        AS ENUM ('CREATED','CONFIRMED','PACKING','SHIPPED','DELIVERED','CANCELLED','RETURNED');
CREATE TYPE "PaymentMethod"      AS ENUM ('VNPAY','MOMO','ZALOPAY','COD','BANK_TRANSFER');
CREATE TYPE "PaymentStatus"      AS ENUM ('PENDING','PAID','FAILED','REFUNDED','EXPIRED');
CREATE TYPE "ShipmentStatus"     AS ENUM ('PENDING_PICKUP','PICKED_UP','IN_TRANSIT','OUT_FOR_DELIVERY','DELIVERED','FAILED_ATTEMPT','RETURNED','CANCELLED');
CREATE TYPE "SubscriptionPlan"   AS ENUM ('FREE','BASIC','PRO','ENTERPRISE');
CREATE TYPE "SubscriptionStatus" AS ENUM ('ACTIVE','TRIALING','PAST_DUE','CANCELLED','EXPIRED');
CREATE TYPE "NotificationChannel" AS ENUM ('IN_APP','PUSH','SMS','EMAIL');
CREATE TYPE "NotificationStatus" AS ENUM ('QUEUED','SENT','DELIVERED','FAILED','READ');
CREATE TYPE "DeviceStatus"       AS ENUM ('INACTIVE','ACTIVE','MAINTENANCE','LOST','DECOMMISSIONED');
CREATE TYPE "AlertType"          AS ENUM ('SOS','FALL','VITALS_BP_HIGH','VITALS_BP_LOW','VITALS_HR_HIGH','VITALS_HR_LOW','VITALS_OXYGEN_LOW','VITALS_TEMP_HIGH','VITALS_TEMP_LOW','GEOFENCE_EXIT','LOW_BATTERY');
CREATE TYPE "AlertSeverity"      AS ENUM ('LOW','MEDIUM','HIGH','CRITICAL');
CREATE TYPE "AlertStatus"        AS ENUM ('OPEN','ACKNOWLEDGED','RESOLVED','CLOSED_FALSE');
CREATE TYPE "AuditAction"        AS ENUM ('CREATE','READ','UPDATE','DELETE','LOGIN','LOGOUT','EXPORT','OTHER');
CREATE TYPE "AuditActorType"     AS ENUM ('USER','SELLER','ADMIN','SUPPORT','SYSTEM','ANONYMOUS');

-- 3) Tables — every primary key uses uuidv7() for time-ordered IDs
-- (The actual CREATE TABLE statements are generated by `prisma migrate dev`
-- from prisma/schema.prisma and pasted in here. The `id` column is:
--   id uuid PRIMARY KEY DEFAULT uuidv7()
-- )

-- 4) TimescaleDB hypertables (only after tables exist)
SELECT create_hypertable('health_records', 'measured_at',
  chunk_time_interval => INTERVAL '1 day',
  if_not_exists => TRUE);
SELECT create_hypertable('alerts', 'received_at',
  chunk_time_interval => INTERVAL '7 days',
  if_not_exists => TRUE);
SELECT create_hypertable('audit_logs', 'occurred_at',
  chunk_time_interval => INTERVAL '30 days',
  if_not_exists => TRUE);

-- 5) Retention policy (PDPA: 7 years for audit logs)
SELECT add_retention_policy('audit_logs', INTERVAL '7 years', if_not_exists => TRUE);

-- 6) Row-Level Security (defence-in-depth — always enable, even if NestJS
--    code is the only entry point)
ALTER TABLE "users"            ENABLE ROW LEVEL SECURITY;
ALTER TABLE "orders"           ENABLE ROW LEVEL SECURITY;
ALTER TABLE "payments"         ENABLE ROW LEVEL SECURITY;
ALTER TABLE "health_records"   ENABLE ROW LEVEL SECURITY;
ALTER TABLE "alerts"           ENABLE ROW LEVEL SECURITY;
ALTER TABLE "audit_logs"       ENABLE ROW LEVEL SECURITY;

-- Example RLS policy (other services add their own):
-- Users can only read their own profile
-- CREATE POLICY user_self_read ON "users"
--   FOR SELECT USING (id = current_setting('app.current_user_id', true)::uuid);
